ALTER TYPE "PurchaseStatus" ADD VALUE IF NOT EXISTS 'PARTIALLY_RECEIVED';
ALTER TYPE "PurchaseStatus" ADD VALUE IF NOT EXISTS 'PENDING_PAYMENT';
ALTER TYPE "PurchaseStatus" ADD VALUE IF NOT EXISTS 'PAID';
CREATE TYPE "PaymentMethod" AS ENUM ('CASH', 'BANK_TRANSFER', 'CARD', 'CREDIT');
CREATE TYPE "PurchaseDocumentType" AS ENUM ('INVOICE', 'RECEIPT', 'CREDIT_NOTE', 'OTHER');
CREATE TABLE "Supplier" ("id" UUID NOT NULL, "companyId" UUID NOT NULL, "ruc" TEXT, "businessName" TEXT NOT NULL, "tradeName" TEXT, "address" TEXT, "phone" TEXT, "email" TEXT, "contactName" TEXT, "paymentTermsDays" INTEGER NOT NULL DEFAULT 30, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Supplier_pkey" PRIMARY KEY ("id"));
ALTER TABLE "Purchase" ADD COLUMN "supplierId" UUID, ADD COLUMN "expectedDeliveryAt" TIMESTAMP(3), ADD COLUMN "warehouseId" UUID, ADD COLUMN "paymentMethod" "PaymentMethod" NOT NULL DEFAULT 'CREDIT', ADD COLUMN "currency" TEXT NOT NULL DEFAULT 'PEN', ADD COLUMN "subtotal" DECIMAL(12,2) NOT NULL DEFAULT 0, ADD COLUMN "taxAmount" DECIMAL(12,2) NOT NULL DEFAULT 0, ADD COLUMN "discountAmount" DECIMAL(12,2) NOT NULL DEFAULT 0;
ALTER TABLE "PurchaseItem" ADD COLUMN "receivedQuantity" DECIMAL(14,3) NOT NULL DEFAULT 0, ADD COLUMN "discount" DECIMAL(12,2) NOT NULL DEFAULT 0, ADD COLUMN "taxRate" DECIMAL(5,2) NOT NULL DEFAULT 18;
CREATE TABLE "PurchaseReceipt" ("id" UUID NOT NULL, "purchaseId" UUID NOT NULL, "warehouseId" UUID NOT NULL, "receivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "notes" TEXT, "receivedById" UUID, CONSTRAINT "PurchaseReceipt_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PurchaseReceiptLine" ("id" UUID NOT NULL, "receiptId" UUID NOT NULL, "purchaseItemId" UUID NOT NULL, "receivedQuantity" DECIMAL(14,3) NOT NULL, "damagedQuantity" DECIMAL(14,3) NOT NULL DEFAULT 0, "lotNumber" TEXT, "expiresAt" TIMESTAMP(3), CONSTRAINT "PurchaseReceiptLine_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PurchaseDocument" ("id" UUID NOT NULL, "purchaseId" UUID NOT NULL, "type" "PurchaseDocumentType" NOT NULL, "series" TEXT, "number" TEXT NOT NULL, "issuedAt" TIMESTAMP(3) NOT NULL, "dueAt" TIMESTAMP(3), "fileUrl" TEXT, "xmlUrl" TEXT, CONSTRAINT "PurchaseDocument_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AccountsPayable" ("id" UUID NOT NULL, "purchaseId" UUID NOT NULL, "originalAmount" DECIMAL(12,2) NOT NULL, "paidAmount" DECIMAL(12,2) NOT NULL DEFAULT 0, "dueAt" TIMESTAMP(3), "status" TEXT NOT NULL DEFAULT 'PENDING', CONSTRAINT "AccountsPayable_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SupplierPayment" ("id" UUID NOT NULL, "payableId" UUID NOT NULL, "amount" DECIMAL(12,2) NOT NULL, "method" "PaymentMethod" NOT NULL, "paidAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "reference" TEXT, CONSTRAINT "SupplierPayment_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Supplier_companyId_ruc_key" ON "Supplier"("companyId", "ruc"); CREATE INDEX "Supplier_companyId_businessName_idx" ON "Supplier"("companyId", "businessName"); CREATE UNIQUE INDEX "PurchaseDocument_purchaseId_key" ON "PurchaseDocument"("purchaseId"); CREATE UNIQUE INDEX "PurchaseDocument_type_series_number_key" ON "PurchaseDocument"("type", "series", "number"); CREATE UNIQUE INDEX "AccountsPayable_purchaseId_key" ON "AccountsPayable"("purchaseId");
ALTER TABLE "Supplier" ADD CONSTRAINT "Supplier_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "Company"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Purchase" ADD CONSTRAINT "Purchase_supplierId_fkey" FOREIGN KEY ("supplierId") REFERENCES "Supplier"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "Purchase" ADD CONSTRAINT "Purchase_warehouseId_fkey" FOREIGN KEY ("warehouseId") REFERENCES "Warehouse"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "PurchaseReceipt" ADD CONSTRAINT "PurchaseReceipt_purchaseId_fkey" FOREIGN KEY ("purchaseId") REFERENCES "Purchase"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "PurchaseReceipt" ADD CONSTRAINT "PurchaseReceipt_warehouseId_fkey" FOREIGN KEY ("warehouseId") REFERENCES "Warehouse"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "PurchaseReceiptLine" ADD CONSTRAINT "PurchaseReceiptLine_receiptId_fkey" FOREIGN KEY ("receiptId") REFERENCES "PurchaseReceipt"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "PurchaseReceiptLine" ADD CONSTRAINT "PurchaseReceiptLine_purchaseItemId_fkey" FOREIGN KEY ("purchaseItemId") REFERENCES "PurchaseItem"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "PurchaseDocument" ADD CONSTRAINT "PurchaseDocument_purchaseId_fkey" FOREIGN KEY ("purchaseId") REFERENCES "Purchase"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "AccountsPayable" ADD CONSTRAINT "AccountsPayable_purchaseId_fkey" FOREIGN KEY ("purchaseId") REFERENCES "Purchase"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "SupplierPayment" ADD CONSTRAINT "SupplierPayment_payableId_fkey" FOREIGN KEY ("payableId") REFERENCES "AccountsPayable"("id") ON DELETE CASCADE ON UPDATE CASCADE;
